import { test } from "@playwright/test";

test("debug overflow", async ({ page }) => {
  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto("/");
  await page.evaluate(() => { document.documentElement.style.fontSize = "200%"; });
  const data = await page.evaluate(() => {
    const selectors = [".setup-section", ".setup-grid", ".setup-copy", ".setup-tabs", ".setup-tablist", ".setup-tab", ".section"];
    return selectors.map((selector) => {
      const el = document.querySelector(selector) as HTMLElement | null;
      if (!el) return { selector, missing: true };
      const rect = el.getBoundingClientRect();
      const cs = getComputedStyle(el);
      return { selector, left: rect.left, right: rect.right, width: rect.width, overflowX: cs.overflowX, minWidth: cs.minWidth, flexWrap: cs.flexWrap, scrollWidth: el.scrollWidth, clientWidth: el.clientWidth };
    });
  });
  console.log(JSON.stringify(data, null, 2));
  console.log("root", await page.evaluate(() => ({ scrollWidth: document.documentElement.scrollWidth, innerWidth: window.innerWidth })));
});

import { test } from "@playwright/test";

test("debug overflow", async ({ page }) => {
  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto("/");
  await page.evaluate(() => { document.documentElement.style.fontSize = "200%"; });
  const data = await page.evaluate(() => {
    const root = document.documentElement;
    const body = document.body;
    const wide = [...document.querySelectorAll("*")].map((el) => {
      const rect = el.getBoundingClientRect();
      return { tag: el.tagName, cls: (el as HTMLElement).className?.toString().slice(0, 60), text: el.textContent?.trim().slice(0, 40), left: rect.left, right: rect.right, width: rect.width, scrollWidth: (el as HTMLElement).scrollWidth, clientWidth: (el as HTMLElement).clientWidth, pos: getComputedStyle(el).position };
    }).filter((item) => item.scrollWidth > item.clientWidth + 1 || item.right > 391);
    return { root: { sw: root.scrollWidth, cw: root.clientWidth }, body: { sw: body.scrollWidth, cw: body.clientWidth, rect: body.getBoundingClientRect().toJSON() }, wide: wide.slice(0, 40) };
  });
  console.log(JSON.stringify(data, null, 2));
});

